// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 1000000000000000000);
    }

    function testFuzz_property(address actor, uint256 value) public {
        // Keep the fuzzed domain wide but make the wager value admissible:
        // the contract requires msg.value == betLimit.
        value = c.currentBetLimit();

        // The test contract is the owner (it deployed c), so it may open the contract.
        c.OpenToThePublic();

        // A non-owner who is also the transaction origin tries to wager exactly betLimit.
        // In the reference, openToPublic was set to true, so this succeeds.
        // In the mutant, openToPublic remains false, so isOpenToPublic() reverts.
        bool ok;
        vm.deal(actor, value);
        vm.prank(actor, actor);
        try c.wager{value: value}() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: after the owner opens the contract to the public, any
        // real-person non-owner with no prior wager can wager exactly the bet limit.
        // Reference: true for all inputs. Mutant: false for every actor.
        assertTrue(ok);
    }
}
